// Parity test against goref/.../internal/hierarchy/zz_tsparity_test.go.

//! rankDAG / build parity against Go fixtures generated by the temporary
//! goref/d2/d2layouts/d2talalayout/internal/hierarchy/zz_tsparity_test.go
//! (shipped as tests/fixtures/go-unit/hierarchy-cases.json).
use crate::*;
use serde_json::Value;

#[test]
fn rank_and_build_parity() {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../tests/fixtures/go-unit/hierarchy-cases.json");
    let data = std::fs::read(&path).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    let cases: Vec<Value> = serde_json::from_slice(&data).unwrap();
    let ctx = gocompat::context::Background();
    let (mut pass, mut fail) = (0, 0);
    for (ci, c) in cases.iter().enumerate() {
        let g = layoutgraph::NewGraph();
        let mut byID: Map<i64, NodeRef> = Map::default();
        for id in c["Nodes"].as_array().unwrap() {
            let id = id.as_i64().unwrap();
            let n = layoutgraph::NewNode(id, 10.0, 10.0);
            g.AddNewNodeToContainer(None, &n);
            byID.insert(id, n);
        }
        if let Some(edges) = c["Edges"].as_array() {
            for (i, e) in edges.iter().enumerate() {
                let edge = g.Connect(&byID[&e["From"].as_i64().unwrap()], &byID[&e["To"].as_i64().unwrap()]);
                {
                    let mut eb = edge.bm();
                    eb.ID = i as i64 + 1;
                    eb.SourceArrowhead = e["Src"].as_str().unwrap().to_string();
                    eb.TargetArrowhead = e["Dst"].as_str().unwrap().to_string();
                }
                let w = e["Weight"].as_i64().unwrap();
                if w > 0 {
                    edge.SetHierarchyRankWeight(w);
                }
            }
        }
        let wantErr = c["Err"].as_bool().unwrap();
        let wantNil = c["Nil"].as_bool().unwrap();
        let (gotErr, gotNil, levels, levelCount): (bool, bool, Map<i64, i64>, i64) = if c["Kind"] == "rank" {
            match rankDAG(&ctx, Some(&g)) {
                Err(_) => (true, false, Map::default(), 0),
                Ok(r) => (false, false, r.nodeToLevel.iter().map(|(n, &l)| (n.id(), l)).collect(), r.levelCount),
            }
        } else {
            let force = c["Force"].as_bool().unwrap();
            match build(&ctx, &g, force, &Candidates(&g), None) {
                Err(_) => (true, false, Map::default(), 0),
                Ok(None) => (false, true, Map::default(), 0),
                Ok(Some(h)) => (false, false, h.Levels().entries().iter().map(|(n, l)| (n.id(), *l)).collect(), h.b().LevelCount),
            }
        };
        let mut ok = gotErr == wantErr && gotNil == wantNil;
        if ok && !wantErr && !wantNil {
            let want: Map<i64, i64> = c["Levels"]
                .as_object()
                .unwrap()
                .iter()
                .map(|(k, v)| (k.parse::<i64>().unwrap(), v.as_i64().unwrap()))
                .collect();
            ok = want == levels && c["LevelCount"].as_i64().unwrap() == levelCount;
        }
        if ok {
            pass += 1;
        } else {
            fail += 1;
            if fail <= 5 {
                eprintln!("case {ci} ({}) differs: err {gotErr}/{wantErr} nil {gotNil}/{wantNil} levels {levels:?} want {}", c["Kind"], c["Levels"]);
            }
        }
    }
    eprintln!("hierarchy rank/build parity: {pass} passed, {fail} failed");
    assert_eq!(fail, 0);
}
